void mainImage(out vec4 utFarge, vec2 pikselKoordinater) {
    vec2 opplosning = iResolution.xy;
    vec2 uv = (pikselKoordinater - 0.5 * opplosning) / opplosning.y;

    float tid = iTime;
    float sveip = sin(tid * 0.5) * 2.5;

    vec3 straleStart = vec3(sveip, 0.8, 5.5);
    vec3 retningFram = normalize(-straleStart);
    vec3 retningHoyre = normalize(cross(retningFram, vec3(0.0, 1.0, 0.0)));
    vec3 retningOpp = cross(retningHoyre, retningFram);
    vec3 straleRetning = normalize(uv.x * retningHoyre + uv.y * retningOpp + 1.2 * retningFram);

    vec4 sluttFarge = vec4(0.0);

    for(int i = 0; i < 5; i++) {
        float lag = float(i);
        float planAvstand = (lag * 0.8 - 1.6 - straleStart.z) / straleRetning.z;

        if(planAvstand > 0.0) {
            vec3 treffPunkt = straleStart + straleRetning * planAvstand;
            vec2 posBasis = treffPunkt.xy * 1.3333333;
            vec2 posOrigo = treffPunkt.xy;
            vec2 posBeregnet = posBasis * (1.0 + 0.1 * lag);

            float vinkelBredde = 0.57119866;

            float skala1 = 3.0 + 0.55 * sin(tid * 0.37 + lag * 0.4);
            float skala2 = 1.1 + 0.22 * sin(tid * 1.1 + 1.3 + lag * 0.3);
            float skala3 = 0.25 + 0.08 * sin(tid * 1.6 + 2.7 + lag * 0.2);

            float roteringsHastighet1 = -0.18 * tid + lag * 0.1;
            float roteringsHastighet2 = 0.36 * tid - lag * 0.15;
            float roteringsHastighet3 = -0.6 * tid + lag * 0.2;

            float vridning1 = 0.12 * sin(tid * 0.17 + 2.0);
            float vridning2 = 1.3 * sin(tid * 0.23 + 1.7);

            float endeligAvstand = 1e9;

            float cos1 = cos(roteringsHastighet1);
            float sin1 = sin(roteringsHastighet1);
            mat2 rotasjon1 = mat2(cos1, -sin1, sin1, cos1);
            vec2 domene1 = rotasjon1 * posBeregnet;
            float sektor1 = floor(atan(-domene1.y, domene1.x) / vinkelBredde + 0.5);

            for(int ii = -1; ii <= 1; ii++) {
                float identifikator1 = sektor1 + float(ii);
                vec4 vinkler1 = identifikator1 * vinkelBredde - vec4(0.0, 11.0, 33.0, 0.0);
                mat2 matriseIdentifikator1 = mat2(cos(vinkler1.x), cos(vinkler1.y), cos(vinkler1.z), cos(vinkler1.w));
                vec2 polarPosisjon1 = domene1 * matriseIdentifikator1 - vec2(skala1, 0.0);

                float vridningsVinkel1 = (identifikator1 - 11.0 * floor(identifikator1 / 11.0 + 0.5)) * vridning1;
                mat2 matriseVridning1 = mat2(cos(vridningsVinkel1), -sin(vridningsVinkel1), sin(vridningsVinkel1), cos(vridningsVinkel1));
                polarPosisjon1 = matriseVridning1 * polarPosisjon1;

                float avstandI = 1e9;

                float cos2 = cos(roteringsHastighet2);
                float sin2 = sin(roteringsHastighet2);
                mat2 rotasjon2 = mat2(cos2, -sin2, sin2, cos2);
                vec2 domene2 = rotasjon2 * polarPosisjon1;
                float sektor2 = floor(atan(-domene2.y, domene2.x) / vinkelBredde + 0.5);

                for(int jj = -1; jj <= 1; jj++) {
                    float identifikator2 = sektor2 + float(jj);
                    vec4 vinkler2 = identifikator2 * vinkelBredde - vec4(0.0, 11.0, 33.0, 0.0);
                    mat2 matriseIdentifikator2 = mat2(cos(vinkler2.x), cos(vinkler2.y), cos(vinkler2.z), cos(vinkler2.w));
                    vec2 polarPosisjon2 = domene2 * matriseIdentifikator2 - vec2(skala2, 0.0);

                    float vridningsVinkel2 = (identifikator2 - 11.0 * floor(identifikator2 / 11.0 + 0.5)) * vridning2;
                    mat2 matriseVridning2 = mat2(cos(vridningsVinkel2), -sin(vridningsVinkel2), sin(vridningsVinkel2), cos(vridningsVinkel2));
                    polarPosisjon2 = matriseVridning2 * polarPosisjon2;

                    float avstandJ = 1e9;

                    float cos3 = cos(roteringsHastighet3);
                    float sin3 = sin(roteringsHastighet3);
                    mat2 rotasjon3 = mat2(cos3, -sin3, sin3, cos3);
                    vec2 domene3 = rotasjon3 * polarPosisjon2;
                    float sektor3 = floor(atan(-domene3.y, domene3.x) / vinkelBredde + 0.5);

                    for(int mm = -1; mm <= 1; mm++) {
                        float identifikator3 = sektor3 + float(mm);
                        vec4 vinkler3 = identifikator3 * vinkelBredde - vec4(0.0, 11.0, 33.0, 0.0);
                        mat2 matriseIdentifikator3 = mat2(cos(vinkler3.x), cos(vinkler3.y), cos(vinkler3.z), cos(vinkler3.w));
                        vec2 polarPosisjon3 = domene3 * matriseIdentifikator3 - vec2(skala3, 0.0);

                        float avstandM = length(polarPosisjon3) - 0.13;

                        float utjevningM = clamp(0.5 + 0.5 * (avstandM - avstandJ) / 0.05, 0.0, 1.0);
                        avstandJ = mix(avstandM, avstandJ, utjevningM) - 0.05 * utjevningM * (1.0 - utjevningM);
                    }

                    float utjevningJ = clamp(0.5 + 0.5 * (avstandJ - avstandI) / 0.08, 0.0, 1.0);
                    avstandI = mix(avstandJ, avstandI, utjevningJ) - 0.08 * utjevningJ * (1.0 - utjevningJ);
                }

                float utjevningI = clamp(0.5 + 0.5 * (avstandI - endeligAvstand) / 0.25, 0.0, 1.0);
                endeligAvstand = mix(avstandI, endeligAvstand, utjevningI) - 0.25 * utjevningI * (1.0 - utjevningI);
            }

            float positivAvstand = max(0.0, endeligAvstand);
            float palettForskyvning = positivAvstand * 0.65 - 0.12 - tid * 0.05;
            vec3 palettFarge = 0.5 + 0.5 * cos(6.2831853 * (palettForskyvning + vec3(0.0, 0.33, 0.67)));

            float bolge = 0.84 + 0.16 * cos(170.0 * positivAvstand);
            vec3 ytreFarge = palettFarge * bolge;
            ytreFarge += vec3(0.85, 1.0, 0.35) * exp(-14.0 * positivAvstand) * 1.6;
            ytreFarge *= exp(-0.3 * positivAvstand);

            float lysIntensitet = pow(0.5 + 0.5 * sin(30.0 * length(posOrigo)), 8.0);
            vec3 indreFarge = mix(vec3(0.04, 0.168, 0.176), vec3(0.962, 1.248, 1.196), lysIntensitet);
            indreFarge *= 0.85 + 0.3 * (1.0 - exp(5.0 * endeligAvstand));
            indreFarge *= smoothstep(0.12, 0.4, length(posOrigo));

            vec4 naverendeFarge = vec4(endeligAvstand > 0.0 ? ytreFarge : indreFarge, 1.0);
            naverendeFarge.rgb *= 1.0 - 0.85 / exp(15.06 * abs(endeligAvstand));

            if(endeligAvstand > 0.0) {
                naverendeFarge.rgb *= 1.15 + 0.1 * cos(80.0 * endeligAvstand);
            }

            float omrissIntensitet = 1.0 - smoothstep(0.0, 0.015, abs(endeligAvstand) - 0.002);
            naverendeFarge.rgb = mix(naverendeFarge.rgb, vec3(2.5), omrissIntensitet);

            float dekkevne = endeligAvstand <= 0.0 ? 1.0 : (i == 0 ? 1.0 : exp(-1.2 * positivAvstand) * 0.6);
            vec4 lagFarge = vec4(naverendeFarge.rgb * exp(-0.15 * planAvstand), dekkevne);

            sluttFarge.rgb = mix(sluttFarge.rgb, lagFarge.rgb, lagFarge.a);
            sluttFarge.a = max(sluttFarge.a, lagFarge.a);
        }
    }

    float vinjettering = pow(smoothstep(0.65, 1.1, length(uv)), 2.0) * 0.9;
    sluttFarge.rgb = mix(sluttFarge.rgb, vec3(0.0), clamp(vinjettering, 0.0, 1.0));

    utFarge = vec4(sluttFarge.rgb, 1.0);
}
